// TEC-379 (DT-BE-8): list contract (docs/list-contract.md). status and
// priority sort by their rank (open → cancelled, low → urgent), subject by
// the subject organization name; due_at keeps tasks without a deadline
// last in both directions; id is the tiebreak. q matches the title or the
// description (the caller escapes LIKE wildcards).
func (q *Queries) ListTasks(ctx context.Context, arg ListTasksParams) ([]ListTasksRow, error) {
	rows, err := q.db.Query(ctx, listTasks,
		arg.BrandID,
		arg.Statuses,
		arg.Priorities,
		arg.SubjectOrgUuids,
		arg.AssigneeUserID,
		arg.DueAfter,
		arg.DueBefore,
		arg.CreatedFrom,
		arg.CreatedBefore,
		arg.Q,
		arg.SortDesc,
		arg.SortKey,
		arg.RowOffset,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTasksRow{}
	for rows.Next() {
		var i ListTasksRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrganizationID,
			&i.BrandID,
			&i.SubjectOrgID,
			&i.Title,
			&i.Description,
			&i.AssigneeUserID,
			&i.Priority,
			&i.DueAt,
			&i.Status,
			&i.Source,
			&i.CreatedByUserID,
			&i.ClosedByUserID,
			&i.ClosedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DueSoonNotifiedAt,
			&i.OverdueNotifiedAt,
			&i.AutoRuleID,
			&i.AutoPeriod,
			&i.SubjectUuid,
			&i.SubjectName,
			&i.SubjectType,
			&i.AssigneeUuid,
			&i.AssigneeName,
			&i.AssigneeSurname,
			&i.CreatorUuid,
			&i.CreatorName,
			&i.CreatorSurname,
			&i.CommentCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

